function results = run_grader_tests(only)
%RUN_GRADER_TESTS  Run every IHW3 MATLAB Grader test against the files on the path.
%
%   results = run_grader_tests           every problem; errors if any test fails
%   results = run_grader_tests("P06")    one problem only; never errors
%
%   GENERATED by build_tests.py from the same source as IHW3_GRADER_SETUP.md.
%   Every test body below is printed verbatim on its problem card, so a test
%   that passes here passes in MATLAB Grader. Do not edit by hand.

    if nargin < 1, only = ""; end
    only = string(only);

    T = {
        'P01', 1, 'The constructor reads the regression', 2, @t_P01_T1
        'P01', 2, 'Engine size at P_SL = 600 hp', 2, @t_P01_T2
        'P01', 3, 'The engine follows P_SL', 1, @t_P01_T3
        'P01', 4, 'The range guard', 1, @t_P01_T4
        'P02', 1, 'The constructor reads the sub-blocks', 2, @t_P02_T1
        'P02', 2, 'The exposed wing', 3, @t_P02_T2
        'P02', 3, 'Tail sizing', 3, @t_P02_T3
        'P02', 4, 'Wetted areas', 3, @t_P02_T4
        'P02', 5, 'Everything follows S_ref and P_SL, except the fuselage', 2, @t_P02_T5
        'P02', 6, 'Wing fuel volume', 1, @t_P02_T6
        'P03', 1, 'Injection and the constructor', 2, @t_P03_T1
        'P03', 2, 'C_D0 and the polar at S_ref = 130, P_SL = 600', 3, @t_P03_T2
        'P03', 3, 'C_D0 follows the wing and the engine', 2, @t_P03_T3
        'P04', 1, 'Empty weight II, all seven rows', 4, @t_P04_T1
        'P04', 2, 'Evaluated at the PASSED weight', 2, @t_P04_T2
        'P04', 3, 'The build-up follows the geometry', 2, @t_P04_T3
        'P04', 4, 'Empty weight III', 3, @t_P04_T4
        'P04', 5, 'An unknown method stops the analysis', 1, @t_P04_T5
        'P05', 1, 'The power-index method is unchanged', 2, @t_P05_T1
        'P05', 2, 'The drag-based power balance', 3, @t_P05_T2
        'P05', 3, 'The limit follows the drag polar', 2, @t_P05_T3
        'P06', 1, 'The cruise weight fraction', 3, @t_P06_T1
        'P06', 2, 'Flown at the real lift coefficient', 2, @t_P06_T2
        'P06', 3, 'Flown with the current wing', 2, @t_P06_T3
        'P06', 4, 'The sub-segment count', 2, @t_P06_T4
        'P07', 1, 'The loiter weight fraction', 3, @t_P07_T1
        'P07', 2, 'Flown with the current wing, not the IHW1 rule', 2, @t_P07_T2
        'P08', 1, 'The first climb, sea level to 8000 ft', 3, @t_P08_T1
        'P08', 2, 'The second climb starts where the previous segment ended', 2, @t_P08_T2
        'P08', 3, 'The climb follows the engine', 2, @t_P08_T3
        'P08', 4, 'A climb that gains no height burns nothing', 1, @t_P08_T4
        'P08', 5, 'Too little power to climb', 2, @t_P08_T5
        'P09', 1, 'The eight segment fractions', 3, @t_P09_T1
        'P09', 2, 'Bookkeeping and the reserve', 2, @t_P09_T2
        'P09', 3, 'Dispatch on the type, not the position', 1, @t_P09_T3
        'P10', 1, 'The takeoff-weight closure', 2, @t_P10_T1
        'P10', 2, 'A closure that cannot close', 1, @t_P10_T2
        'P10', 3, 'Relaxation', 2, @t_P10_T3
        'P11', 1, 'The constraint analysis sizes the wing and the engine', 3, @t_P11_T1
        'P11', 2, 'Fuel, empty weight and closure on the STEP 0 airplane', 3, @t_P11_T2
        'P11', 3, 'STEP 0 writes the states, not the answer', 2, @t_P11_T3
        'P11', 4, 'The residuals', 2, @t_P11_T4
        'P12', 1, 'The converged airplane', 3, @t_P12_T1
        'P12', 2, 'Every state is relaxed', 2, @t_P12_T2
        'P12', 3, 'The bundle holds the converged airplane', 2, @t_P12_T3
        'P12', 4, 'A different guess, the same airplane, both residuals closed', 2, @t_P12_T4
    };

    results = struct('problem', {}, 'test', {}, 'title', {}, 'weight', {}, 'pass', {}, 'message', {});
    for i = 1:size(T, 1)
        if strlength(only) > 0 && T{i,1} ~= only
            continue;
        end
        ok = true;  msg = "";
        try
            feval(T{i,5});
        catch ME
            ok = false;  msg = string(ME.message);
        end
        results(end+1) = struct('problem', string(T{i,1}), 'test', T{i,2}, ...
            'title', string(T{i,3}), 'weight', T{i,4}, 'pass', ok, 'message', msg); %#ok<AGROW>
        if ok, tag = 'PASS'; else, tag = 'FAIL'; end
        fprintf('RESULT %s T%d %s w=%d  %s\n', T{i,1}, T{i,2}, tag, T{i,4}, T{i,3});
        if ~ok, fprintf('       -> %s\n', msg); end
    end

    earned = sum([results([results.pass]).weight]);
    possible = sum([results.weight]);
    fprintf('\nSCORE %d / %d   (%d of %d tests pass)\n', earned, possible, ...
            nnz([results.pass]), numel(results));
    if strlength(only) == 0 && any(~[results.pass])
        error('run_grader_tests:Failed', '%d test(s) failed.', nnz(~[results.pass]));
    end
end


function t_P01_T1()
% Problem 1, Test 1 - The constructor reads the regression
    obj = ttpa_disciplines();
    assert(abs(obj.prop.k_W_engine - 5.47) <= 1e-12, 'k_W_engine must be read from J.propulsion.engine_weight_coefficient');
    assert(abs(obj.prop.n_W_engine - 0.78) <= 1e-12, 'n_W_engine must be read from J.propulsion.engine_weight_exponent');
    assert(abs(obj.prop.k_L_engine - 0.32) <= 1e-12, 'k_L_engine must be read from J.propulsion.engine_length_coefficient');
    assert(abs(obj.prop.n_L_engine - 0.424) <= 1e-12, 'n_L_engine must be read from J.propulsion.engine_length_exponent');
    assert(isequal(obj.prop.bhp_range(:).', [60 500]), 'bhp_range must be read from J.propulsion.bhp_range_of_validity');
    assert(isstring(obj.prop.engine_scaling_class) && obj.prop.engine_scaling_class == "opposed", 'engine_scaling_class must be the string "opposed"');
end

function t_P01_T2()
% Problem 1, Test 2 - Engine size at P_SL = 600 hp
    obj = ttpa_disciplines();
    obj.prop.P_SL = 600;
    assert(abs(obj.prop.rated_bhp_per_engine() - 300) <= 1e-9, 'the rated power is per ENGINE: P_SL / n_engines');
    [W_total, W_each] = obj.prop.engine_weight();
    assert(abs(W_each - 467.887998) <= 1e-4*467.887998, 'W_each = k_W_engine * bhp^n_W_engine, with bhp of ONE engine');
    assert(abs(W_total - 935.775996) <= 1e-4*935.775996, 'W_total must be n_engines times W_each');
    assert(abs(obj.prop.engine_length() - 3.592935) <= 1e-4*3.592935, 'engine_length = k_L_engine * bhp^n_L_engine, for ONE engine');
end

function t_P01_T3()
% Problem 1, Test 3 - The engine follows P_SL
    obj = ttpa_disciplines();
    obj.prop.P_SL = 700;
    [~, W_each] = obj.prop.engine_weight();
    assert(abs(W_each - 527.667567) <= 1e-4*527.667567, 'engine_weight must be recomputed from the current P_SL');
    assert(abs(obj.prop.engine_length() - 3.835613) <= 1e-4*3.835613, 'engine_length must be recomputed from the current P_SL');
end

function t_P01_T4()
% Problem 1, Test 4 - The range guard
    obj = ttpa_disciplines();
    obj.prop.P_SL = 1200;
    lastwarn('');
    bhp = obj.prop.rated_bhp_per_engine();
    [~, id] = lastwarn;
    assert(strcmp(id, 'TtpaProp:BhpOutOfRange'), 'outside 60-500 bhp the guard must WARN, with identifier TtpaProp:BhpOutOfRange');
    assert(abs(bhp - 600) <= 1e-9, 'the guard must warn AND still return the value');
    obj.prop.P_SL = NaN;
    threw = false;
    try
        obj.prop.rated_bhp_per_engine();
    catch ME
        threw = strcmp(ME.identifier, 'TtpaProp:PowerNotSet');
    end
    assert(threw, 'with P_SL = NaN the guard must error, with identifier TtpaProp:PowerNotSet');
end

function t_P02_T1()
% Problem 2, Test 1 - The constructor reads the sub-blocks
    obj = ttpa_disciplines();
    g = obj.geom;
    assert(abs(g.V_ht - 0.8) <= 1e-12 && abs(g.L_ht - 15) <= 1e-12, 'horizontal_tail: volume coefficient or arm is wrong');
    assert(abs(g.V_vt - 0.065) <= 1e-12 && abs(g.L_vt - 17) <= 1e-12, 'vertical_tail: volume coefficient or arm is wrong');
    assert(abs(g.tc_ht - 0.12) <= 1e-12 && abs(g.tc_vt - 0.12) <= 1e-12, 'tail thickness ratios are wrong');
    assert(abs(g.w_fus - 5.0) <= 1e-12 && abs(g.h_fus - 5.75) <= 1e-12, 'fuselage width or height is wrong');
    assert(abs(g.l_nose + g.l_cabin + g.l_cone - 31.6) <= 1e-9, 'fuselage nose, cabin or tail-cone length is wrong');
    assert(abs(g.d_nacelle - 2.8) <= 1e-12 && abs(g.k_nacelle_length - 2.0) <= 1e-12, 'nacelle diameter or length factor is wrong');
    assert(isnan(g.S_ref), 'S_ref must start as NaN: the sizing loop sets it');
end

function t_P02_T2()
% Problem 2, Test 2 - The exposed wing
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    g = obj.geom;
    assert(abs(g.b - 32.249031) <= 1e-4*32.249031, 'the span is wrong - it is given, check you did not change it');
    assert(abs(g.S_exposed_wing - 102.545508) <= 1e-4*102.545508, 'S_exposed_wing is wrong: S_ref minus the chord integrated across the fuselage width');
end

function t_P02_T3()
% Problem 2, Test 3 - Tail sizing
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    assert(abs(obj.geom.S_ht - 29.660333) <= 1e-4*29.660333, 'S_ht = V_h * S_ref * MAC / L_ht');
    assert(abs(obj.geom.S_vt - 16.029665) <= 1e-4*16.029665, 'S_vt = V_v * S_ref * b / L_vt - the vertical tail uses the SPAN, not the MAC');
end

function t_P02_T4()
% Problem 2, Test 4 - Wetted areas
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    g = obj.geom;
    assert(abs(TtpaGeom.wetted_from_exposed(10, 0.18) - 20.706) <= 1e-9, 'above t/c = 0.05: S_exposed * (1.977 + 0.52 t/c), Raymer Eq. 7.12');
    assert(abs(TtpaGeom.wetted_from_exposed(10, 0.04) - 20.03) <= 1e-9, 'below t/c = 0.05: 2.003 S_exposed, Raymer Eq. 7.11');
    assert(abs(g.S_wet_fuselage - 383.2225) <= 1e-4*383.2225, 'fuselage wetted area: 3.4 (A_top + A_side)/2, Raymer Eq. 7.13');
    assert(abs(g.l_nacelle - 7.185870) <= 1e-4*7.185870, 'l_nacelle = k_nacelle_length times the ENGINE length from the propulsion model');
    assert(abs(g.S_wet_nacelle - 126.420437) <= 1e-4*126.420437, 'S_wet_nacelle = n_engines * pi * d_nacelle * l_nacelle');
    assert(abs(g.S_wet - 812.754284) <= 1e-4*812.754284, 'S_wet must add all five components');
    assert(abs(g.S_wet_over_S_ref - 6.251956) <= 1e-4*6.251956, 'S_wet_over_S_ref = S_wet / S_ref');
end

function t_P02_T5()
% Problem 2, Test 5 - Everything follows S_ref and P_SL, except the fuselage
    obj = ttpa_disciplines();
    obj.geom.S_ref = 150;
    obj.prop.P_SL  = 600;
    g = obj.geom;
    assert(abs(g.S_ht - 36.761895) <= 1e-4*36.761895, 'S_ht must follow S_ref');
    assert(abs(g.S_vt - 19.867642) <= 1e-4*19.867642, 'S_vt must follow S_ref');
    assert(abs(g.S_wet_over_S_ref - 5.810908) <= 1e-4*5.810908, 'S_wet_over_S_ref must follow S_ref');
    assert(abs(g.S_wet_fuselage - 383.2225) <= 1e-4*383.2225, 'the fuselage is sized by the cabin: it must NOT follow S_ref');
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 700;
    assert(abs(g.S_wet_nacelle - 134.959271) <= 1e-4*134.959271, 'the nacelles must follow P_SL');
    assert(abs(g.S_wet_wing - 209.931164) <= 1e-4*209.931164, 'the wing must NOT follow P_SL');
end

function t_P02_T6()
% Problem 2, Test 6 - Wing fuel volume
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    assert(abs(obj.geom.wing_fuel_volume() - 35.418157) <= 1e-4*35.418157, 'wing_fuel_volume is wrong: check tau = (t/c)_tip/(t/c)_root and the (1 + lambda)^2 denominator');
end

function t_P03_T1()
% Problem 3, Test 1 - Injection and the constructor
    obj = ttpa_disciplines();
    assert(obj.aero.geom == obj.geom, 'obj.aero.geom must be the SAME TtpaGeom object that ttpa_disciplines injected');
    assert(abs(obj.aero.Cfe - 0.0045) <= 1e-12, 'Cfe must be read from J.aerodynamics.Cfe');
    assert(abs(obj.aero.CD0_reference - 0.028) <= 1e-12, 'CD0_reference must be read from J.aerodynamics.CD0_clean');
    assert(obj.aero.AR == obj.geom.AR, 'AR must come from the geometry model');
end

function t_P03_T2()
% Problem 3, Test 2 - C_D0 and the polar at S_ref = 130, P_SL = 600
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    assert(abs(obj.aero.CD0 - 0.02813380) <= 1e-4*0.02813380, 'CD0 = Cfe * S_wet / S_ref');
    assert(abs(obj.aero.LD_max - 13.454791) <= 1e-4*13.454791, 'LD_max must use the new CD0');
    polar = obj.aero.drag_polar(get_state(0));
    assert(abs(polar.CD0 - 0.02813380) <= 1e-4*0.02813380, 'drag_polar must return the live CD0');
    cfg = obj.aero.get_config_polar(get_state(0), struct('config', "landing_flaps_gear_down", 'propeller_stopped', false));
    assert(abs(cfg.CD0 - 0.11313380) <= 1e-4*0.11313380, 'the configuration polars must build on the live CD0');
end

function t_P03_T3()
% Problem 3, Test 3 - C_D0 follows the wing and the engine
    obj = ttpa_disciplines();
    obj.geom.S_ref = 150;
    obj.prop.P_SL  = 600;
    assert(abs(obj.aero.CD0 - 0.02614909) <= 1e-4*0.02614909, 'CD0 must follow S_ref');
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 700;
    assert(abs(obj.aero.CD0 - 0.02842938) <= 1e-4*0.02842938, 'CD0 must follow P_SL, through the nacelle wetted area');
    assert(abs(obj.aero.e - 0.810592) <= 1e-4*0.810592, 'the Oswald factor does not depend on size');
end

function t_P04_T1()
% Problem 4, Test 1 - Empty weight II, all seven rows
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    bd = obj.wts.OEW_breakdown(5400);
    assert(abs(bd.wing - 256.363770) <= 1e-4*256.363770, 'wing row: 2.5 lb/ft^2 times the EXPOSED wing area');
    assert(abs(bd.horizontal_tail - 59.320667) <= 1e-4*59.320667, 'horizontal tail row: 2.0 lb/ft^2 times S_ht');
    assert(abs(bd.vertical_tail - 32.059331) <= 1e-4*32.059331, 'vertical tail row: 2.0 lb/ft^2 times S_vt');
    assert(abs(bd.fuselage - 536.5115) <= 1e-4*536.5115, 'fuselage row: 1.4 lb/ft^2 times the fuselage WETTED area');
    assert(abs(bd.landing_gear - 307.8) <= 1e-9, 'landing gear row: 0.057 W_TO');
    assert(abs(bd.installed_engine - 1310.086394) <= 1e-4*1310.086394, 'installed engine row: 1.4 times ALL the bare engines');
    assert(abs(bd.all_else_empty - 540) <= 1e-9, 'all-else row: 0.10 W_TO');
    assert(abs(bd.total - 3042.141662) <= 1e-4*3042.141662, 'total must add all seven rows');
    assert(abs(obj.wts.OEW(5400) - bd.total) <= 1e-9, 'OEW must return the total of OEW_breakdown');
end

function t_P04_T2()
% Problem 4, Test 2 - Evaluated at the PASSED weight
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    obj.wts.W_TO   = 1;
    bd = obj.wts.OEW_breakdown(6000);
    assert(abs(bd.landing_gear - 342) <= 1e-9, 'evaluate every weight-dependent row at the PASSED W_TO, never obj.W_TO');
    assert(abs(bd.all_else_empty - 600) <= 1e-9, 'evaluate every weight-dependent row at the PASSED W_TO, never obj.W_TO');
    assert(abs(bd.total - 3136.341662) <= 1e-4*3136.341662, 'the total at W_TO = 6000 is wrong');
end

function t_P04_T3()
% Problem 4, Test 3 - The build-up follows the geometry
    obj = ttpa_disciplines();
    obj.geom.S_ref = 150;
    obj.prop.P_SL  = 600;
    bd = obj.wts.OEW_breakdown(5400);
    assert(abs(bd.wing - 301.024518) <= 1e-4*301.024518, 'the wing row must follow S_ref');
    assert(abs(bd.horizontal_tail - 73.523789) <= 1e-4*73.523789, 'the tail rows must follow S_ref');
    assert(abs(bd.fuselage - 536.5115) <= 1e-4*536.5115, 'the fuselage row must not follow S_ref');
    assert(abs(bd.total - 3108.681484) <= 1e-4*3108.681484, 'the total at S_ref = 150 is wrong');
end

function t_P04_T4()
% Problem 4, Test 4 - Empty weight III
    obj = ttpa_disciplines();
    obj.geom.S_ref   = 130;
    obj.prop.P_SL    = 600;
    obj.wts.method   = "raymer_ga_III";
    obj.wts.W_energy = 1150;
    bd = obj.wts.OEW_breakdown(5400);
    assert(abs(bd.wing - 338.963531) <= 1e-4*338.963531, 'Raymer Eq. 15.46 wing weight is wrong');
    assert(abs(bd.installed_engine - 1491.688239) <= 1e-4*1491.688239, 'Raymer Eq. 15.52: 2.575 W_en^0.922 N_en, with W_en ONE bare engine');
    assert(abs(bd.total - 3306.343266) <= 1e-4*3306.343266, 'the Empty weight III total is wrong');
    obj.wts.W_energy = NaN;
    bd = obj.wts.OEW_breakdown(5400);
    assert(abs(bd.wing - 330.704826) <= 1e-4*330.704826, 'with no fuel weight yet the W_fw term is ignored (set to 1)');
end

function t_P04_T5()
% Problem 4, Test 5 - An unknown method stops the analysis
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    obj.wts.method = "napkin";
    threw = false;
    try
        obj.wts.OEW_breakdown(5400);
    catch ME
        threw = strcmp(ME.identifier, 'TtpaWeights:UndefinedMethod');
    end
    assert(threw, 'an unknown weight method must error, with identifier TtpaWeights:UndefinedMethod');
end

function t_P05_T1()
% Problem 5, Test 1 - The power-index method is unchanged
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    obj.cons(6).method = "power_index";
    WP_exp = [8.432052 11.242735];
    WP = constraint_cruise_speed([30 40], obj, 6);
    assert(all(abs(WP - WP_exp) <= 1e-4*WP_exp), 'with method "power_index" the IHW2 answer must be unchanged');
end

function t_P05_T2()
% Problem 5, Test 2 - The drag-based power balance
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    WP_exp = [7.126195 8.679851 9.052354];
    [WP, extra] = constraint_cruise_speed([30 40 43], obj, 6);
    assert(isequal(size(WP), [1 3]), 'WP_max must be the same size as WS - use element-by-element operators');
    assert(all(abs(WP - WP_exp) <= 1e-4*WP_exp), 'the drag-based power-loading limit is wrong');
    assert(abs(extra.CL(2) - 0.375787) <= 1e-4*0.375787, 'C_L = beta*(W/S)/q');
    assert(abs(extra.LD(2) - 10.716711) <= 1e-4*10.716711, 'L/D at the required speed is wrong');
end

function t_P05_T3()
% Problem 5, Test 3 - The limit follows the drag polar
    obj = ttpa_disciplines();
    obj.geom.S_ref = 150;
    obj.prop.P_SL  = 600;
    WP_exp = [7.596888 9.200607 9.578309];
    WP = constraint_cruise_speed([30 40 43], obj, 6);
    assert(all(abs(WP - WP_exp) <= 1e-4*WP_exp), 'the drag-based limit must follow the drag polar, and so the wing');
    obj.cons(6).method = "guess";
    threw = false;
    try
        constraint_cruise_speed(40, obj, 6);
    catch ME
        threw = strcmp(ME.identifier, 'constraint_cruise_speed:UndefinedMethod');
    end
    assert(threw, 'an unknown method must error, with identifier constraint_cruise_speed:UndefinedMethod');
end

function t_P06_T1()
% Problem 6, Test 1 - The cruise weight fraction
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [W_out, fuel_used, WF] = segment_cruise_L2(5000, obj, 3);
    assert(abs(WF - 0.83416445) <= 1e-4*0.83416445, 'the cruise weight fraction is wrong');
    assert(abs(fuel_used - 829.177771) <= 1e-4*829.177771, 'fuel_used = (1 - WF) * W_in');
    assert(abs(W_out - 4170.822229) <= 1e-4*4170.822229, 'W_out = W_in * WF');
end

function t_P06_T2()
% Problem 6, Test 2 - Flown at the real lift coefficient
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [~, ~, WF, info] = segment_cruise_L2(5000, obj, 3);
    assert(info.n_sub == 12, 'n_sub must be read from obj.miss.cruise_segments');
    assert(abs(info.CL - 0.33357474) <= 1e-4*0.33357474, 'the mean cruise C_L is wrong: C_L = W/(q*S_ref) in every piece');
    assert(abs(info.LD - 9.918921) <= 1e-4*9.918921, 'the mean cruise L/D is wrong');
    assert(WF < 0.87501940 - 0.01, 'flying at L/D_max is the IHW1 answer, not this one');
end

function t_P06_T3()
% Problem 6, Test 3 - Flown with the current wing
    obj = ttpa_disciplines();
    obj.geom.S_ref = 150;
    obj.prop.P_SL  = 600;
    [~, ~, WF] = segment_cruise_L2(5000, obj, 3);
    assert(abs(WF - 0.82790073) <= 1e-4*0.82790073, 'the cruise must be flown with the CURRENT wing, obj.geom.S_ref');
end

function t_P06_T4()
