function t_P07_T1()
% Problem 7, Test 1 - The loiter weight fraction
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [W_out, fuel_used, WF, info] = segment_loiter_L2(4200, obj, 6);
    assert(abs(WF - 0.98865969) <= 1e-5*0.98865969, 'the loiter weight fraction is wrong');
    assert(abs(fuel_used - 47.629301) <= 1e-4*47.629301, 'fuel_used = (1 - WF) * W_in');
    assert(abs(W_out - 4152.370699) <= 1e-6*4152.370699, 'W_out = W_in * WF');
    assert(abs(info.CL - 0.74621120) <= 1e-4*0.74621120, 'C_L = W/(q*S_ref) at the loiter speed and altitude');
    assert(abs(info.LD - 13.453388) <= 1e-4*13.453388, 'L/D at the loiter C_L is wrong');
end

function t_P07_T2()
% Problem 7, Test 2 - Flown with the current wing, not the IHW1 rule
    obj = ttpa_disciplines();
    obj.geom.S_ref = 150;
    obj.prop.P_SL  = 600;
    [~, ~, WF] = segment_loiter_L2(4200, obj, 6);
    assert(abs(WF - 0.98898625) <= 1e-5*0.98898625, 'the loiter must be flown with the CURRENT wing, obj.geom.S_ref');
    obj.geom.S_ref = 130;
    [~, ~, WF] = segment_loiter_L2(4200, obj, 6);
    assert(abs(WF - 0.98691784) > 1e-4, 'L/D = 0.866 L/D_max is the IHW1 answer, not this one');
end

function t_P08_T1()
% Problem 8, Test 1 - The first climb, sea level to 8000 ft
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [W_out, fuel_used, WF, info] = segment_climb_L2(4920, obj, 2);
    assert(abs(fuel_used - 14.976315) <= 1e-4*14.976315, 'the fuel burned from sea level to 8000 ft is wrong');
    assert(abs(W_out - 4905.023685) <= 1e-6*4905.023685, 'W_out = W_in * WF');
    assert(abs(WF - 0.99695603) <= 1e-6*0.99695603, 'WF = W at the top of the climb / W_in');
    assert(abs(info.CL - 1.3112817) <= 1e-4*1.3112817, 'climb at C_L = sqrt(3*CD0/K1), the minimum-power lift coefficient');
    assert(abs(info.time_hr - 0.07925085) <= 1e-4*0.07925085, 'the time to climb is wrong');
end

function t_P08_T2()
% Problem 8, Test 2 - The second climb starts where the previous segment ended
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [~, fuel_used] = segment_climb_L2(4000, obj, 5);
    assert(abs(fuel_used - 5.189087) <= 1e-4*5.189087, 'segment 5 climbs from the altitude segment 4 ended at, 0 ft, to 4000 ft');
    obj.miss.segments(4).alt_ft = 2000;
    [~, fuel_used] = segment_climb_L2(4000, obj, 5);
    assert(abs(fuel_used - 2.631546) <= 1e-4*2.631546, 'with the descent ending at 2000 ft, segment 5 climbs only from 2000 to 4000 ft - take h_start from segment seg_no - 1');
end

