function t_P08_T5()
% Problem 8, Test 5 - Too little power to climb
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 60;
    threw = false;
    try
        segment_climb_L2(4920, obj, 2);
    catch ME
        threw = strcmp(ME.identifier, 'segment_climb_L2:CannotClimb');
    end
    assert(threw, 'with too little power the climb must stop with identifier segment_climb_L2:CannotClimb');
end

function t_P09_T1()
% Problem 9, Test 1 - The eight segment fractions
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [fuel_burned, segment_weight, segment_wf] = run_mission_L2(5000, obj);
    wf_exp = [0.984 0.99695603 0.83206056 0.992 0.99869593 0.98864535 0.992 0.992];
    assert(isequal(size(segment_wf), [1 8]), 'one weight fraction per segment');
    assert(all(abs(segment_wf - wf_exp) <= 1e-5*wf_exp), 'the segment weight fractions are wrong');
    assert(abs(sum(fuel_burned) - 1066.267093) <= 1e-4*1066.267093, 'the total mission fuel before reserve is wrong');
    assert(abs(segment_weight(end) - 3933.732907) <= 1e-4*3933.732907, 'the final weight is wrong');
end

function t_P09_T2()
% Problem 9, Test 2 - Bookkeeping and the reserve
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    [fuel_burned, segment_weight, segment_wf] = run_mission_L2(5000, obj);
    assert(abs(segment_weight(1) - 5000) <= 1e-12, 'segment_weight(1) is W_TO');
    assert(all(abs(segment_weight(2:end) - segment_weight(1:end-1).*segment_wf) <= 1e-9*5000), 'each segment must start at the weight the previous one ended at');
    assert(all(abs(fuel_burned - segment_weight(1:end-1).*(1 - segment_wf)) <= 1e-9*5000), 'fuel_burned(k) = W_in(k) * (1 - WF(k))');
    W_fuel = mission_fuel(5000, obj);
    assert(abs(W_fuel - 1130.243119) <= 1e-4*1130.243119, 'mission_fuel must see YOUR segment fuel; it adds the 6 % reserve');
end

function t_P09_T3()
% Problem 9, Test 3 - Dispatch on the type, not the position
    obj = ttpa_disciplines();
    obj.geom.S_ref = 130;
    obj.prop.P_SL  = 600;
    obj.miss.segments(5:6) = [];
    [fuel_burned, ~, segment_wf] = run_mission_L2(5000, obj);
    wf_exp = [0.984 0.99695603 0.83206056 0.992 0.992 0.992];
    assert(isequal(size(segment_wf), [1 6]), 'the loop must run over however many segments the profile has');
    assert(all(abs(segment_wf - wf_exp) <= 1e-5*wf_exp), 'with the loiter removed, segments 5 and 6 are a descent and a landing: switch on the segment TYPE');
    assert(abs(sum(fuel_burned) - 1015.892385) <= 1e-4*1015.892385, 'the fuel of the shortened mission is wrong');
end

function t_P10_T1()
% Problem 10, Test 1 - The takeoff-weight closure
    [W_new, denom] = SizingSteps.togw_update(1200, 3000, 1150, 5400);
    assert(abs(denom - 0.231481481) <= 1e-8, 'denom = 1 - W_fuel/W_TO - W_OEW/W_TO');
    assert(abs(W_new - 5184) <= 1e-6, 'W_new = W_payload / denom');
end

function t_P10_T2()
% Problem 10, Test 2 - A closure that cannot close
    [W_new, denom] = SizingSteps.togw_update(1200, 3500, 2000, 5400);
    assert(isnan(W_new), 'when denom <= 0 no positive weight closes: return NaN');
    assert(abs(denom - (1 - 2000/5400 - 3500/5400)) <= 1e-12, 'denom must still be returned when it is negative');
end

function t_P10_T3()
% Problem 10, Test 3 - Relaxation
    assert(abs(SizingSteps.relax(5000, 6000, 0.45) - 5450) <= 1e-9, 'x = x_old + w*(x_new - x_old)');
    assert(abs(SizingSteps.relax(5000, 6000, 1) - 6000) <= 1e-9, 'w = 1 is the full step');
    assert(abs(SizingSteps.relax(606.149, 606.149, 0.2) - 606.149) <= 1e-12, 'at the fixed point relaxation changes nothing');
    assert(abs(SizingSteps.relax(6000, 5000, 0.3) - 5700) <= 1e-9, 'relaxation must work in both directions');
end

function t_P11_T1()
% Problem 11, Test 1 - The constraint analysis sizes the wing and the engine
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    row = sizing_pass(obj, W0, P0, S0, WS_sweep);
    assert(abs(row.WS - 43.240424) <= 1e-5*43.240424, 'W/S must be the least-engine corner from matching_envelope (its 4th output)');
    assert(abs(row.WP - 9.0833073) <= 1e-5*9.0833073, 'W/P must be the least-engine corner (its 5th output)');
    assert(abs(row.S_ref_new - 115.632538) <= 1e-5*115.632538, 'S_new = W0 / (W/S)');
    assert(abs(row.P_SL_new - 550.460294) <= 1e-5*550.460294, 'P_new = W0 / (W/P): power loading is inverted, so DIVIDE');
end

function t_P11_T2()
% Problem 11, Test 2 - Fuel, empty weight and closure on the STEP 0 airplane
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    row = sizing_pass(obj, W0, P0, S0, WS_sweep);
    assert(abs(row.CD0 - 0.02812221) <= 1e-5*0.02812221, 'the pass must be flown by the airplane written in STEP 0 (S0 and P0), not by S_new');
    assert(abs(row.W_fuel - 1124.492673) <= 1e-5*1124.492673, 'the mission fuel is evaluated at W0, on the STEP 0 airplane');
    assert(abs(row.OEW - 2871.915932) <= 1e-5*2871.915932, 'the empty weight is built at W0, from the STEP 0 airplane');
    assert(abs(row.W_TO_new - 5978.528744) <= 1e-5*5978.528744, 'W_new is the takeoff-weight closure at W0');
end

function t_P11_T3()
% Problem 11, Test 3 - STEP 0 writes the states, not the answer
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    obj.geom.S_ref = 200;
    obj.prop.P_SL  = 900;
    row = sizing_pass(obj, W0, P0, S0, WS_sweep);
    assert(abs(obj.geom.S_ref - S0) <= 1e-12 && abs(obj.prop.P_SL - P0) <= 1e-12, 'STEP 0 writes P0 and S0 into the airplane; S_new and P_new are NOT written back');
    assert(abs(row.W_TO_new - 5978.528744) <= 1e-5*5978.528744, 'the pass must not depend on what the airplane held before it was called');
end

function t_P11_T4()
% Problem 11, Test 4 - The residuals
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    row = sizing_pass(obj, W0, P0, S0, WS_sweep);
    assert(abs(row.res_W - 0.16367384) <= 1e-5*0.16367384, 'res_W = |W_new - W0| / W_new');
    assert(abs(row.res_P - 0.01802083) <= 1e-4*0.01802083, 'res_P = |P_new - P0| / P_new');
    assert(abs(row.res_S - 0.11101946) <= 1e-5*0.11101946, 'res_S = |S_new - S0| / S_new');
end

function t_P12_T1()
% Problem 12, Test 1 - The converged airplane
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    opts = struct('W0', W0, 'P0', P0, 'S0', S0, 'WS_sweep', WS_sweep, ...
                  'tol', J.sizing.tol_rel, 'max_iter', J.sizing.max_iter, ...
                  'relax', J.sizing.relaxation);
    [hist, converged, state] = sizing_mainloop(obj, opts);
    assert(converged, 'the loop must report converged = true');
    assert(abs(state.W0 - 5414.742648) <= 1e-5*5414.742648, 'the converged W_TO is wrong');
    assert(abs(state.P0 - 606.148989) <= 1e-5*606.148989, 'the converged P_SL is wrong');
    assert(abs(state.S0 - 125.224206) <= 1e-5*125.224206, 'the converged S_ref is wrong');
    assert(state.n_iter == 34 && numel(hist) == 34, 'at relaxation 0.45 the loop closes in 34 passes: test BOTH residuals against tol');
end

function t_P12_T2()
% Problem 12, Test 2 - Every state is relaxed
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    opts = struct('W0', W0, 'P0', P0, 'S0', S0, 'WS_sweep', WS_sweep, ...
                  'tol', J.sizing.tol_rel, 'max_iter', J.sizing.max_iter, ...
                  'relax', J.sizing.relaxation);
    hist = sizing_mainloop(obj, opts);
    assert(abs(hist(2).W_TO - 5440.337935) <= 1e-6*5440.337935, 'pass 2 must start from W0 + w*(W_new - W0), not from W_new');
    assert(abs(hist(2).P_SL - 545.004430) <= 1e-6*545.004430, 'relax the power as well');
    assert(abs(hist(2).S_ref - 122.693142) <= 1e-6*122.693142, 'relax the wing area as well');
end

function t_P12_T3()
% Problem 12, Test 3 - The bundle holds the converged airplane
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    opts = struct('W0', W0, 'P0', P0, 'S0', S0, 'WS_sweep', WS_sweep, ...
                  'tol', J.sizing.tol_rel, 'max_iter', J.sizing.max_iter, ...
                  'relax', J.sizing.relaxation);
    [hist, ~, state] = sizing_mainloop(obj, opts);
    assert(abs(obj.geom.S_ref - state.S0) <= 1e-12 && abs(obj.prop.P_SL - state.P0) <= 1e-12, 'on return obj must hold the converged S_ref and P_SL');
    assert(abs(state.W0 - hist(end).W_TO_new) <= 1e-12, 'on convergence take the pass''s own answer, unrelaxed');
end

function t_P12_T4()
% Problem 12, Test 4 - A different guess, the same airplane, both residuals closed
    obj = ttpa_disciplines();
    J  = jsondecode(fileread(ttpa_requirements_path()));
    W0 = J.sizing.W_TO_guess_lbf;
    S0 = J.sizing.S_ref_guess_ft2;
    P0 = W0 / J.constraints.design_point.power_loading_lb_per_hp;
    obj.geom.S_ref = S0;
    obj.prop.P_SL  = P0;
    WS_sweep = wing_loading_sweep(obj);
    opts = struct('W0', W0, 'P0', P0, 'S0', S0, 'WS_sweep', WS_sweep, ...
                  'tol', J.sizing.tol_rel, 'max_iter', J.sizing.max_iter, ...
                  'relax', J.sizing.relaxation);
    opts.W0 = 8000;
    opts.P0 = 900;
    opts.S0 = 180;
    [hist, converged, state] = sizing_mainloop(obj, opts);
    assert(converged && abs(state.W0 - 5414.742648) <= 1e-5*5414.742648, 'a different starting guess must reach the same airplane');
    assert(hist(end).res_W < opts.tol && hist(end).res_P < opts.tol, 'the loop may stop only when BOTH residuals are below tol - from this guess the power settles last');
    assert(state.n_iter == 33, 'from this guess the loop closes in 33 passes when both residuals are tested');
end
